import{_ as s,H as n,f as e,i as p}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"18 | RISC-V指令精讲（三）：跳转指令实现与调试","description":"","frontmatter":{},"headers":[{"level":2,"title":"为什么要有跳转指令","slug":"为什么要有跳转指令","link":"#为什么要有跳转指令","children":[]},{"level":2,"title":"RISC-V 的跳转指令格式","slug":"risc-v-的跳转指令格式","link":"#risc-v-的跳转指令格式","children":[]},{"level":2,"title":"无条件跳转指令：jal 指令","slug":"无条件跳转指令-jal-指令","link":"#无条件跳转指令-jal-指令","children":[]},{"level":2,"title":"无条件跳转指令：jalr 指令","slug":"无条件跳转指令-jalr-指令","link":"#无条件跳转指令-jalr-指令","children":[]},{"level":2,"title":"重点回顾","slug":"重点回顾","link":"#重点回顾","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"计算机基础实战课/18｜RISC-V指令精讲（三）：跳转指令实现与调试.md","filePath":"计算机基础实战课/18｜RISC-V指令精讲（三）：跳转指令实现与调试.md","lastUpdated":1795560006000}'),i={name:"计算机基础实战课/18｜RISC-V指令精讲（三）：跳转指令实现与调试.md"};function t(l,a,r,E,o,c){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h1 id="_18-risc-v指令精讲-三-跳转指令实现与调试" tabindex="-1">18 | RISC-V指令精讲（三）：跳转指令实现与调试 <a class="header-anchor" href="#_18-risc-v指令精讲-三-跳转指令实现与调试" aria-label="Permalink to &quot;18 | RISC-V指令精讲（三）：跳转指令实现与调试&quot;">​</a></h1><p>你好，我是 LMOS。</p><p>在第五节课，我们曾经提到 RV32I 有两种跳转指令，即无条件跳转指令和有条件的跳转指令。</p><p>不过，前面我们只是简单了解了跳转指令长什么样，并没有深入讲解。接下来的两节课，我们就好好研究一下跳转指令的原理，挨个指令做调试。</p><p>这节课我们从源头说起，弄明白为什么需要有跳转指令存在，然后再熟悉一下无条件跳转指令。至于有条件跳转指令，我们放在下节课继续学习。这节课代码，你可以从这里下载。</p><h2 id="为什么要有跳转指令" tabindex="-1">为什么要有跳转指令 <a class="header-anchor" href="#为什么要有跳转指令" aria-label="Permalink to &quot;为什么要有跳转指令&quot;">​</a></h2><p>我们不妨回忆一下：C 语言中 if、for、goto 等流程控制语句都是如何实现的？还有 C 语言的函数是如何调用和返回的？</p><p>通过前面的学习，我们了解到 CPU 执行指令是由 PC 寄存器指向的。每次执行完指令，CPU的 PC 寄存器就会自动增加一条指令大小的数值，使之指向下一条指令，如此循环，这就导致CPU 只能在 PC 寄存器的引导下顺序地执行指令，而 C 语言函数就是一条条指令组成的。显然，只靠这样的机制，C 语言无法实现流程控制和函数的调用与返回。</p><p>如果现在有一种机制，它能够修改 CPU 里 PC 寄存器的值，或者根据特定的条件来修改 CPU的 PC 寄存器的值，让 PC 寄存器能指向特定的内存地址，读取里面的指令并运行。这样，上述问题就会迎刃而解了。</p><p>让我用一段 C 语言代码为例，给你分解一下这个原理，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int add()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>   int sum = 0;</span></span>
<span class="line"><span>   for(int i = 0; i &lt; 100; i++)</span></span>
<span class="line"><span>       sum++;</span></span>
<span class="line"><span>   return sum;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>上述代码中，for 函数包含了条件流程控制和循环流程控制。在编译过程中，C 语言编译器会将它拆分为三段，伪代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add:</span></span>
<span class="line"><span>   int sum = 0;</span></span>
<span class="line"><span>   int i = 0;</span></span>
<span class="line"><span>label1:</span></span>
<span class="line"><span>   i &lt; 100 = false goto lable2</span></span>
<span class="line"><span>   sum++;</span></span>
<span class="line"><span>   i++;</span></span>
<span class="line"><span>   goto label1</span></span>
<span class="line"><span>lable2:</span></span>
<span class="line"><span>   return sum;</span></span></code></pre></div><p>以上伪代码中的 goto 用来修改 CPU 的 PC 寄存器的值，使之指向 lable1 或者 lable2，这样CPU 才能执行不同的代码段，从而实现流程控制。这里的 goto 语句就对应着后面要讲的跳转指令。</p><p>说到这里，如果你能再次想起图灵机的读头在那条无限的纸带上跳来跳去的情景，就说明你已经深刻理解了代码的执行原理。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/1.png" alt=""></a></p><h2 id="risc-v-的跳转指令格式" tabindex="-1">RISC-V 的跳转指令格式 <a class="header-anchor" href="#risc-v-的跳转指令格式" aria-label="Permalink to &quot;RISC-V 的跳转指令格式&quot;">​</a></h2><p>前面我们说了，CPU 必须依赖某个机制修改 PC 寄存器的值，让程序能够跳转执行，达到程序流程控制的目的。</p><p>这个机制离不开 CPU 提供的跳转指令，只要执行跳转指令就能修改 PC 寄存器了。在研究无条件跳转指令之前，我们先来看看 RISC-V 的跳转指令格式，它对应的汇编语句格式如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>指令助记符 目标寄存器，源操作数1，源操作数2</span></span></code></pre></div><p>对于无条件跳转指令来说，指令助记符可以是 jal 和 jalr，目标寄存器可以是任何通用寄存器，而源操作数 1 可以是任何通用寄存器，源操作数 2 可以是任何通用寄存器和立即数。</p><p>为什么是目标寄存器而不是 PC 寄存器呢？继续往下看，我会带你找到答案。</p><h2 id="无条件跳转指令-jal-指令" tabindex="-1">无条件跳转指令：jal 指令 <a class="header-anchor" href="#无条件跳转指令-jal-指令" aria-label="Permalink to &quot;无条件跳转指令：jal 指令&quot;">​</a></h2><p>我们先来看看 jal 指令，这是一条无条件的跳转并链接的指令。它的汇编代码书写形式如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jal rd，imm</span></span>
<span class="line"><span>#jal 无条件的跳转并链接的指令</span></span>
<span class="line"><span>#rd 目标寄存器</span></span>
<span class="line"><span>#imm 立即数</span></span></code></pre></div><p>上述代码中，rd 可以是任何通用寄存器。立即数 imm 为 20 位二进制数据。有的文档里会把imm 称为偏移，为了课程前后文的一致性，我们继续沿用立即数的叫法。</p><p>jal 完成的操作用伪代码描述如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rd = pc + 4；</span></span>
<span class="line"><span>pc = pc + 符号扩展（imm &lt;&lt; 1）</span></span></code></pre></div><p>对照代码不难发现，jal 指令首先把 pc+4，即下一条指令地址送给了 rd，然后把 PC 寄存器中的 32 位无符号数据加上 imm&lt;&lt;1，并且进行符号位扩展（因为指令总是 2 或者 4 字节地址对齐的，所以最低位永远为 0），再送给 PC 寄存器。这样就实现了程序的跳转。</p><p>接下来，我们一起写代码验证一下。</p><p>为了方便调试，我们的代码组织结构是这样的：写一个 main.c 文件，在里面写上 main 函数，因为这是链接器所需要的。然后我们需要再写一个 jal.S 文件，用汇编在里面写上 jal_ins函数。</p><p>类似的操作前面两节课反复试验过，就不过多重复了。代码如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.text</span></span>
<span class="line"><span>.global jal_ins</span></span>
<span class="line"><span>jal_ins:</span></span>
<span class="line"><span>   jal a0，imm_l1              #a0=add x0，x0，x0的地址，跳转到imm_l1地址处开始运行</span></span>
<span class="line"><span>   add x0，x0，x0              #相当于nop，什么也不做</span></span>
<span class="line"><span>   add x0，x0，x0</span></span>
<span class="line"><span>imm_l1:</span></span>
<span class="line"><span>   jal a0，imm_l2              #a0=imm_l2的地址，跳转到imm_l2地址处开始运行</span></span>
<span class="line"><span>imm_l2:</span></span>
<span class="line"><span>   jr ra                       #函数返回</span></span></code></pre></div><p>我已经把 jal_ins 函数为你写好了。第一条指令跳转到 imm_l1 地址处开始运行，a0 寄存器保存下一条指令的地址，即 add x0，x0，x0 的地址。</p><p>这条指令没什么实际的实现，x0 是个只读寄存器，始终返回 0。imm_l1 地址处又是一条跳转指令，跳转到 jr ra 指令地址，即 imm_l2 处开始运行。a0 等于 imm_l2 的地址，也会作为函数的返回值返回。</p><p>你可以用 VSCode 打开工程目录，按下“F5”键调试一下。首先，我们把断点停在 jal a0，imm_l1 指令处，效果如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/2.png" alt=""></a></p><p>上图中的状态是执行 jal a0，imm_l1 指令之前，pc 寄存器指向 0x10174 地址，这个地址对应的正是这条 jal a0， imm_l1 指令。</p><p>我们一旦单步调试，程序代码就会跳到 jal a0，imm_l2 指令处，pc + 12 等于 0x10180，a0等于 0x10178，状态如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/3.png" alt=""></a></p><p>果不其然，a0 等于 0x10178，而 pc 等于 0x10180，正是 jal a0，imm_l2 指令。</p><p>我们继续做单步调试，程序代码会跳到 jr ra 指令处，pc + 4 等于 0x10184，a0 也会等于0x10184，存放 jr ra 指令的地址，而 a0 作为函数的返回值进行返回，也就是 jal_ins 函数最后一条指令的地址。</p><p>我们再次进行单步调试，程序将会回到 main 函数中，并打印出返回值，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/4.png" alt=""></a></p><p>可以看到，上图中输出的结果确实是符合预期的，这说明 jal 指令的功能确实跟我们前面描述的一致，能够无条件跳转并链接。</p><h2 id="无条件跳转指令-jalr-指令" tabindex="-1">无条件跳转指令：jalr 指令 <a class="header-anchor" href="#无条件跳转指令-jalr-指令" aria-label="Permalink to &quot;无条件跳转指令：jalr 指令&quot;">​</a></h2><p>让我们加把劲！在 jal.S 文件中再写一个函数——jalr_ins 函数。在这个函数中，我们用 jalr 指令实现函数调用，具体就是给 jalr_ins 函数传递一个函数指针，通过这个函数指针调用这个函数。</p><p>写代码之前，我们先来了解一下 jalr 指令，它同样是一条无条件的跳转并链接的指令。jalr 指令与 jal 指令字面上的不同点，无非就是多了一个字母“r”，这个“r”表示寄存器，相当于 jal 指令的寄存器版本，能够通过寄存器传递跳转地址。</p><p>jalr 的汇编代码书写形式如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jalr rd，rs1，imm</span></span>
<span class="line"><span>#jalr 无条件的跳转并链接的指令</span></span>
<span class="line"><span>#rd 目标寄存器</span></span>
<span class="line"><span>#rs 源寄存器1</span></span>
<span class="line"><span>#imm 立即数</span></span></code></pre></div><p>上述代码中 rd、rs1 可以是任何通用寄存器，立即数 imm 为 12 位二进制数据。jalr 完成的操作用伪代码描述如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rd = pc + 4；</span></span>
<span class="line"><span>pc = (rs1 + 符号扩展(imm &lt;&lt; 1)) &amp; 0xfffffffe</span></span></code></pre></div><p>对比之后我们不难发现，以上代码中和 jal 相同的地方是，开始第一步由 jalr 指令把 pc+4，即下一条指令地址送给 rd。</p><p>而不同之处是，jalr 指令的下一步操作会让 rs1 中的 32 位无符号数据加上 imm&lt;&lt;1，并且进行符号位扩展后与上 0xfffffffe，这也是为了指令要以 2 字节或者 4 字节地址对齐，所以最低位必须为 0，形成一个地址值。完成以上过程后，这个地址值会送给 pc，从而实现程序的跳转。</p><p>下面我们一起写代码验证一下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.global jalr_ins</span></span>
<span class="line"><span>jalr_ins:</span></span>
<span class="line"><span>   addi sp，sp，-16            #在栈中分配16字节的空间</span></span>
<span class="line"><span>   sw  ra，0(sp)               #保存ra寄存器到栈中</span></span>
<span class="line"><span>   jalr ra，a0，0              #ra = lw ra，0(sp)指令的地址，跳转到a0+0的地址处开始运行</span></span>
<span class="line"><span>   lw ra，0(sp)                #从栈中恢复ra寄存器</span></span>
<span class="line"><span>   addi sp，sp，16             #回收栈中分配的16字节的空间</span></span>
<span class="line"><span>   jr ra                       #函数返回</span></span></code></pre></div><p>这段代码 3~4 行和 6~7 行代码的作用是，在栈中分配和回收内存空间的指令，用于保存和恢复 ra 寄存器的内容。</p><p>因为在第 5 行代码中，跳转别的代码中运行，正是用 ra 寄存器来保存地址的，然而在跳转到jalr_ins 函数处运行的时候，同样是使用 ra 寄存器保存返回地址的，如果不保存和恢复 ra 寄存器，jalr_ins 函数将无法返回。</p><p>现在我们调试一下，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/5.png" alt=""></a></p><p>上图中是执行 jalr ra，a0，0 指令之前的状态，a0 寄存器中的值是 0x101a0，这正是 testjalr函数的地址。这条指令能完成类似函数调用的功能，我们一旦单步调试，程序就会跳到testjalr 函数内部开始运行，状态如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/6.png" alt=""></a></p><p>由上图可知，jalr_ins 函数确实调用了 testjalr 函数，也打印出了 testjalr 的地址。下一步将要执行 testjalr 函数的返回语句，会返回 jalr_ins 函数的地址。</p><p>我们继续做单步调试，看看能不能返回到 jalr_ins 函数中，如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/7.png" alt=""></a></p><p>调试结果验证了确实如此，代码流程再次回到了 jalr_ins 函数中。在 jalr_ins 函数中，我们恢复了之前的 ra 寄存器，a0 寄存器中保存着 testjalr 函数的返回值，即 jalr_ins 函数的地址。</p><p>继续单步调试，代码流程就会回到 main 函数。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/8.png" alt=""></a></p><p>如上图所示，main 函数中继续打印出了 jalr_ins 函数的地址，这个结果是正确的，代码流程也符合预期。</p><p>通过调试，我们已经了解了 jal、jalr 指令的功能细节。</p><p>下面，我们来看看 jal_ins 函数和 jalr_ins 函数的二进制数据。其实我们调试 bug 或者做逆向工程，很多时候都需要研究机器码，正好借这次研究指令的机会，我们一起练习一下怎么分析。</p><p>我们打开终端，切换到工程目录下，输入命令：riscv64-unknown-elf-objdump -d ./main.elf &gt;./main.ins，就会得到 main.elf 的反汇编数据文件 main.ins。打开这个文件，就会看到 jal_ins函数和 jalr_ins 函数的二进制数据，我的操作截图如下所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/9.png" alt=""></a></p><p>上图中的反汇编代码中使用了一些伪指令，比如 ret 的机器码是 0x00008067，它就是 jr ra，但是 jr ra 也是伪指令，实际的指令是 jalr x0，ra，0 指令，伪指令是为了方便汇编编程人员才使用的。</p><p>我们再来说说上图中的机器码，0x0040056f 为 jal a0，imm_l2（0x10184），0x000500e7 为jalr ra，a0，0，图里的 jalr a0 就是 jalr ra，a0，0 。</p><p>我们继续拆分 jal 指令和 jalr 指令的各位段的数据，看看它们具体是如何编码的。你不妨结合后面的示意图来理解：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/10.png" alt=""></a></p><p>jal 指令与 jalr 指令是靠操作码区分的。jal 指令的立即数部分编码非常乱，这部分跟芯片设计有关，就不深入讨论了，其数据正常组合起来是 0b00000000000000000010，这个二进制数据左移 1 位等于十六进制数据 0x4。为什么是这样呢？</p><p>回到前面看看 jal 指令的操作，你就明白了：pc+4 正好是 imm_l2 的地址即 0x10184，而 jalr指令编码非常简单，12 位立即数为 0，源寄存器是 a0，目标寄存器是 ra，x1 寄存器的编码就是 1。</p><p>到这里，jal 指令与 jalr 指令我们就讲完了。它们都是无条件跳转指令，并且都可以保存跳转指令的下一条指令的地址，用于返回。但 jal 指令与 jalr 指令跳转的地址大小范围有差别，这主要取决于它们地址数据的编码形式和计算方式。jal 指令是用当前 pc 值加上 20 位立即数，jalr指令是通用寄存器加上 11 位立即数。</p><h2 id="重点回顾" tabindex="-1">重点回顾 <a class="header-anchor" href="#重点回顾" aria-label="Permalink to &quot;重点回顾&quot;">​</a></h2><p>说到这里，这节课的内容就告一段落了，我来给你做个总结。</p><p>因为不管什么程序都不能永无止境地顺序运行下去，所以需要控制程序流程，对数据进行比较判断，根据结果执行相应的动作。这就需要程序能够跳转，所以，一套指令集里就必须要有跳转指令来支持。</p><p>跳转指令又分成有条件跳转指令和无条件跳转指令。我们按照先易后难的顺序，这节课重点研究了无条件的跳转指令，一共是两条指令，即 jal 指令和 jalr 指令。它们在跳转的同时还能保存下一条指令的地址，这类指令常用来实现高级语言（如 C 语言）里的函数调用。</p><p>这节课的要点我给你准备了导图，你可以做个参考。调试验证环节，我建议你自己课后动手多多练习，加深印象。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%AE%A1%E7%AE%97%E6%9C%BA%E5%9F%BA%E7%A1%80%E5%AE%9E%E6%88%98%E8%AF%BE/images/18/11.png" alt=""></a></p><p>下节课我们继续研究有条件跳转指令，敬请期待。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>既然已经有 jal 指令了，为什么还需要 jalr 指令呢？</p><p>期待你在留言区记录收获或疑问，认真思考和主动练习都能让你加深印象。如果感觉这节课还不错，也推荐你把这节课分享给更多朋友。</p>`,90)])])}const A=s(i,[["render",t]]);export{g as __pageData,A as default};
